weights = {"성능": 3, "운영 난이도": 2, "팀 숙련도": 2, "비용": 1}
options = {
    "Kafka":    {"성능": 5, "운영 난이도": 2, "팀 숙련도": 2, "비용": 3},
    "RabbitMQ": {"성능": 3, "운영 난이도": 4, "팀 숙련도": 4, "비용": 4},
}
for name, s in options.items():
    total = sum(weights[k] * s[k] for k in weights)
    print(name, total, "/", 5 * sum(weights.values()))
# Kafka 26 / 40
# RabbitMQ 29 / 40
